import 'package:flutter/material.dart';
import '../../design/app_theme.dart';
import '../../design/brand.dart';
import '../../design/components.dart';

class SplashScreen extends StatelessWidget { const SplashScreen({super.key}); @override Widget build(BuildContext context)=>Scaffold(body:Stack(children:[Positioned.fill(child:CustomPaint(painter:_CircuitPainter())),Center(child:Column(mainAxisSize:MainAxisSize.min,children:[const InspectPinMark(size:72),const SizedBox(height:28),const InspectPinWordmark(),const SizedBox(height:28),SizedBox(width:90,child:LinearProgressIndicator(minHeight:2,color:IpColors.accent,backgroundColor:IpColors.border))]))])); }

class OnboardingScreen extends StatefulWidget { const OnboardingScreen({super.key,required this.onComplete});final VoidCallback onComplete;@override State<OnboardingScreen> createState()=>_OnboardingScreenState(); }
class _OnboardingScreenState extends State<OnboardingScreen>{int page=0;final controller=PageController();static const pages=[('Capture precision','Frame de-energized electronics with the wearable camera.','camera'),('Ask naturally','Use voice on the device or a grounded question in the app.','mic'),('Keep the evidence','Review observations, uncertainty and professional reports.','report')];@override void dispose(){controller.dispose();super.dispose();}@override Widget build(BuildContext context)=>Scaffold(body:SafeArea(child:Column(children:[Padding(padding:const EdgeInsets.fromLTRB(24,22,24,10),child:Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[const InspectPinWordmark(compact:true),TextButton(onPressed:widget.onComplete,child:const Text('Skip'))])),Expanded(child:PageView(controller:controller,onPageChanged:(value)=>setState(()=>page=value),children:[for(final item in pages)Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[const DeviceConcept(height:260),const SizedBox(height:36),IpEyebrow('0${pages.indexOf(item)+1} / 0${pages.length}'),const SizedBox(height:12),Text(item.$1,textAlign:TextAlign.center,style:Theme.of(context).textTheme.displayLarge),const SizedBox(height:16),Text(item.$2,textAlign:TextAlign.center,style:Theme.of(context).textTheme.bodyLarge)]))])),Padding(padding:const EdgeInsets.all(24),child:Row(children:[Row(children:[for(var i=0;i<pages.length;i++)AnimatedContainer(duration:const Duration(milliseconds:220),margin:const EdgeInsets.only(right:6),width:i==page?24:7,height:7,decoration:BoxDecoration(color:i==page?IpColors.accent:IpColors.border,borderRadius:BorderRadius.circular(8)))]),const Spacer(),FilledButton(onPressed:(){if(page==pages.length-1){widget.onComplete();}else{controller.nextPage(duration:const Duration(milliseconds:260),curve:Curves.easeOutCubic);}},child:Text(page==pages.length-1?'Get started':'Continue'))]))])));}
class _CircuitPainter extends CustomPainter{@override void paint(Canvas canvas,Size size){final paint=Paint()..color=IpColors.accent.withValues(alpha:.06)..style=PaintingStyle.stroke..strokeWidth=1;for(var i=0;i<6;i++){final y=size.height*(.14+i*.15);canvas.drawPath(Path()..moveTo(0,y)..lineTo(size.width*.25,y)..lineTo(size.width*.36,y-30)..lineTo(size.width,y-30),paint);}}@override bool shouldRepaint(covariant CustomPainter oldDelegate)=>false;}
